// Replays testdata/corpus.json (generated by testdata/gencorpus) and compares
// with testdata/oracle.json, the output of
// `php oracle/scripts/jsonmanip-dump.php configsource` on official PHP 8.4
// running Composer f83588392df43d4fd027d84d26de459946ef4e80's
// JsonConfigSource. Never edit oracle.json by hand. Regenerate with:
//
//	go run ./internal/configsource/testdata/gencorpus > internal/configsource/testdata/corpus.json
//	podman run --rm --network=none -v $PWD/.cache/oracle-source:/oracle-source:ro \
//	  -v $PWD/oracle/scripts:/scripts:ro -v $PWD/internal/configsource/testdata:/data:ro \
//	  localhost/gocomposer-oracle:8.4 php /scripts/jsonmanip-dump.php configsource /data/corpus.json \
//	  > internal/configsource/testdata/oracle.json
