//go:build unix

package configsource

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"testing"

	"gocomposer/internal/jsonmanip"
	"gocomposer/internal/phpjson"
)

func decodeTagged(raw json.RawMessage) (phpjson.Value, error) {
	var plain any
	if err := json.Unmarshal(raw, &plain); err != nil {
		return nil, err
	}
	switch t := plain.(type) {
	case nil, bool, string:
		return t, nil
	case map[string]any:
	default:
		return nil, fmt.Errorf("unexpected %T", plain)
	}
	var tagged struct {
		T     string              `json:"t"`
		V     json.RawMessage     `json:"v"`
		B64   string              `json:"b64"`
		Class string              `json:"class"`
		Items [][]json.RawMessage `json:"items"`
	}
	if err := json.Unmarshal(raw, &tagged); err != nil {
		return nil, err
	}
	switch tagged.T {
	case "int":
		var n int64
		err := json.Unmarshal(tagged.V, &n)
		return n, err
	case "float":
		var s string
		if err := json.Unmarshal(tagged.V, &s); err != nil {
			return nil, err
		}
		return strconv.ParseFloat(s, 64)
	case "bytes":
		b, err := base64.StdEncoding.DecodeString(tagged.B64)
		return string(b), err
	case "array", "object":
		m := phpjson.NewMap()
		for _, it := range tagged.Items {
			var k string
			if err := json.Unmarshal(it[0], &k); err != nil {
				return nil, err
			}
			v, err := decodeTagged(it[1])
			if err != nil {
				return nil, err
			}
			m.Set(k, v)
		}
		m.ForceObject = tagged.T == "object"
		return m, nil
	}
	return nil, fmt.Errorf("unknown tag %q", tagged.T)
}

func runOp(src *Source, op string, a []phpjson.Value) error {
	s := func(i int) string { v, _ := a[i].(string); return v }
	switch op {
	case "addRepository":
		return src.AddRepository(s(0), a[1], a[2].(bool))
	case "insertRepository":
		return src.InsertRepository(s(0), a[1], s(2), int(a[3].(int64)))
	case "setRepositoryUrl":
		return src.SetRepositoryUrl(s(0), s(1))
	case "removeRepository":
		return src.RemoveRepository(s(0))
	case "addConfigSetting":
		return src.AddConfigSetting(s(0), a[1])
	case "removeConfigSetting":
		return src.RemoveConfigSetting(s(0))
	case "addProperty":
		return src.AddProperty(s(0), a[1])
	case "removeProperty":
		return src.RemoveProperty(s(0))
	case "addLink":
		return src.AddLink(s(0), s(1), s(2))
	case "removeLink":
		return src.RemoveLink(s(0), s(1))
	}
	return fmt.Errorf("unknown op %s", op)
}

func TestOracleConfigSource(t *testing.T) {
	old := syscall.Umask(0o22)
	defer syscall.Umask(old)

	var corpus struct {
		Cases []struct {
			File     string          `json:"file"`
			Contents json.RawMessage `json:"contents"`
			Auth     bool            `json:"auth"`
			Ops      []struct {
				M    string            `json:"m"`
				Args []json.RawMessage `json:"args"`
			} `json:"ops"`
		} `json:"cases"`
	}
	var oracle struct {
		Results []struct {
			Events []struct {
				Op  string `json:"op"`
				Exc *struct {
					Class   string `json:"class"`
					Message string `json:"message"`
				} `json:"exc"`
				Contents json.RawMessage `json:"contents"`
				Mode     *int            `json:"mode"`
			} `json:"events"`
		} `json:"results"`
	}
	for name, dst := range map[string]any{"testdata/corpus.json": &corpus, "testdata/oracle.json": &oracle} {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, dst); err != nil {
			t.Fatal(err)
		}
	}
	if len(corpus.Cases) != len(oracle.Results) {
		t.Fatal("corpus/oracle length mismatch")
	}
	failures, ops := 0, 0
	for i, c := range corpus.Cases {
		dir := t.TempDir()
		path := filepath.Join(dir, c.File)
		if string(c.Contents) != "null" {
			v, err := decodeTagged(c.Contents)
			if err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(path, []byte(v.(string)), 0o644); err != nil {
				t.Fatal(err)
			}
			if err := os.Chmod(path, 0o644); err != nil {
				t.Fatal(err)
			}
		}
		src := New(path, c.Auth)
		for j, op := range c.Ops {
			ops++
			want := oracle.Results[i].Events[j]
			args := make([]phpjson.Value, len(op.Args))
			for k, raw := range op.Args {
				v, err := decodeTagged(raw)
				if err != nil {
					t.Fatal(err)
				}
				args[k] = v
			}
			err := runOp(src, op.M, args)
			var msg string
			var exc *jsonmanip.Exception
			switch {
			case want.Exc != nil:
				wantMsg := strings.ReplaceAll(want.Exc.Message, "@DIR@", dir)
				if !errors.As(err, &exc) || exc.Class != want.Exc.Class || exc.Message != wantMsg {
					msg = fmt.Sprintf("PHP threw %s(%q), Go: %v", want.Exc.Class, wantMsg, err)
				}
			case err != nil:
				msg = fmt.Sprintf("Go error %v", err)
			}
			if msg == "" {
				data, rerr := os.ReadFile(path)
				if string(want.Contents) == "null" {
					if rerr == nil {
						msg = "PHP left no file, Go wrote one"
					}
				} else {
					wv, _ := decodeTagged(want.Contents)
					if rerr != nil {
						msg = "file missing in Go"
					} else if string(data) != wv.(string) {
						msg = fmt.Sprintf("contents differ\nPHP:\n%s\nGo:\n%s", wv, data)
					} else if st, err := os.Stat(path); err == nil && want.Mode != nil && int(st.Mode().Perm()) != *want.Mode {
						msg = fmt.Sprintf("mode PHP %o, Go %o", *want.Mode, st.Mode().Perm())
					}
				}
			}
			if msg != "" {
				failures++
				if failures <= 15 {
					t.Errorf("case %d op %d %s(%s) [%s]: %s", i, j, op.M, argsString(op.Args), c.File, msg)
				}
				break
			}
		}
	}
	if failures > 0 {
		t.Errorf("%d of %d cases differ", failures, len(corpus.Cases))
	}
	t.Logf("%d cases, %d operations", len(corpus.Cases), ops)
}

func argsString(args []json.RawMessage) string {
	var parts []string
	for _, a := range args {
		parts = append(parts, string(a))
	}
	return strings.Join(parts, ", ")
}
